    {
      "category": "embedding_representation",
      "rationale": "Learn a positive coordinate gain shared by tied history and candidate embeddings in each category's single GRU4Rec model. Zero-initialized log gains preserve the initial unit-normalized representation while allowing coordinate importance to adapt. Keep dimensions, GRU topology, scoring, loss and optimizer fixed.",
      "edits": [
        {
          "find": "class UnitNormItemEmbedding(nn.Embedding):\n    def forward(self, indices: torch.Tensor) -> torch.Tensor:\n        embeddings = super().forward(indices)\n        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)",
          "replace": "class UnitNormItemEmbedding(nn.Embedding):\n    def __init__(self, *args, **kwargs):\n        super().__init__(*args, **kwargs)\n        self.log_coordinate_gain = nn.Parameter(self.weight.new_zeros(self.embedding_dim))\n\n    def forward(self, indices: torch.Tensor) -> torch.Tensor:\n        embeddings = super().forward(indices)\n        embeddings = embeddings * self.log_coordinate_gain.exp()\n        embeddings = torch.nn.functional.normalize(embeddings, p=2, dim=-1, eps=1e-12)\n        return embeddings.masked_fill(indices.eq(0).unsqueeze(-1), 0.0)"
        },
